export type Dictionary = (typeof dictionaries)["en"];

// Category detail stories can differ in shape between categories (some include a
// components checklist, others do not), so the shared renderer treats every
// optional field defensively.
export type MaterialCategoryStory = {
  eyebrow: string;
  headline: string;
  intro: string[];
  accessTitle?: string;
  accessParagraphs?: string[];
  componentsTitle?: string;
  componentsIntro?: string;
  components?: string[];
  componentsNote?: string;
  sections: { title: string; paragraphs: string[] }[];
  flowTitle: string;
  flowLead: string;
  flowIntro: string;
  flow: string[];
  flowResult?: string;
  closingTitle: string;
  closingParagraphs: string[];
  closingStrong: string;
};

export function getMaterialCategoryStory(locale: Locale, slug: string): MaterialCategoryStory | undefined {
  const stories = getDictionary(locale).materialCategoryStories as Record<string, MaterialCategoryStory | undefined>;
  return stories[slug];
}

export function getDictionary(locale: Locale): Dictionary {
  return (dictionaries[locale] ?? dictionaries.en) as Dictionary;
}
